#pragma once

#include "sfx/adapters/storage/sqlite_storage.hpp"
#include <filesystem>
#include <string>
#include <string_view>

namespace sfx::platform::linux_host::layout {
inline constexpr std::string_view schema = "linux-lowercase-v1";
inline constexpr std::string_view marker_relative = "config/linux-layout.v1";
inline constexpr std::string_view marker_text = "SFX-LINUX-LAYOUT-1\nlinux-lowercase-v1\n";

// Only call for paths owned/generated by SFX. Append arbitrary owner/content,
// DOS/game and vendor path components separately and preserve their spelling.
std::filesystem::path physical_relative(std::string_view canonical_owned);
std::filesystem::path path(const std::filesystem::path& root, std::string_view canonical_owned);
std::string owned_name(std::string_view generated_leaf);
std::string archive_relative(std::string_view native_relative);
adapters::storage::SqliteStorageSettings storage_settings(const std::filesystem::path& root);

// No writes. Missing/mixed/legacy owned names or an invalid marker refuse.
void refuse_legacy_or_mixed(const std::filesystem::path& root);
void preflight(const std::filesystem::path& root);
void require_current(const std::filesystem::path& root);
// Caller already owns the normal installation lock. A marker may be created
// only for a fresh empty config/data state without an existing receipt.
void initialize_or_verify(const std::filesystem::path& root);
} // namespace sfx::platform::linux_host::layout
